import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long k = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        long total = 0, biggest = 0;
        for (int i = 0; i < n; i++) {
            total += a[i];
            biggest = Math.max(biggest, a[i]);
        }
        if (total % k != 0 || biggest > total / k) {
            System.out.println("no");
        } else {
            long target = total / k;
            int count = (int) n;
            int full = (1 << count) - 1;
            boolean[] ok = new boolean[1 << count];
            long[] sums = new long[1 << count];
            ok[0] = true;
            for (int mask = 0; mask < full; mask++) {
                if (!ok[mask]) continue;
                long fill = sums[mask] % target;
                for (int j = 0; j < count; j++) {
                    if ((mask >> j & 1) != 0) continue;
                    if (fill + a[j] <= target) {
                        int nm = mask | (1 << j);
                        ok[nm] = true;
                        sums[nm] = sums[mask] + a[j];
                    }
                }
            }
            System.out.println(ok[full] ? "yes" : "no");
        }
    }
}
